<?php
if (!defined('ABSPATH')) exit;
final class Asenka_YOOtheme_Image_Guard {
 const VERSION=AYIG_VERSION; const OPTION='ayig_findings'; const LOG='ayig_audit';
 static function init(){add_action('admin_menu',[__CLASS__,'menu']);add_action('admin_post_ayig',[__CLASS__,'action']); if(defined('WP_CLI') && WP_CLI) self::cli();}
 static function menu(){add_management_page('Asenka YOOtheme Image Guard','YOOtheme Image Guard','manage_options','asenka-yootheme-image-guard',[__CLASS__,'page']);}
 static function roots(){return [WP_CONTENT_DIR.'/uploads'];}
 static function versions(){ $out=[]; foreach(wp_get_themes() as $slug=>$theme){if(stripos($slug,'yootheme')!==false || stripos($theme->get('Name'),'yootheme')!==false){$v=$theme->get('Version');$out[]=['type'=>'theme','name'=>$theme->get('Name'),'version'=>$v,'status'=>self::status($v)];}} foreach(get_plugins() as $path=>$plugin){if(stripos($path,'yootheme')!==false || stripos($plugin['Name'],'yootheme')!==false){$v=$plugin['Version'];$out[]=['type'=>'plugin','name'=>$plugin['Name'],'version'=>$v,'status'=>self::status($v)];}}return $out; }
 static function status($v){if(!preg_match('/^\d+\.\d+\.\d+/',$v))return 'unknown';return version_compare($v,'5.0.0','>=') && version_compare($v,'5.0.53','<')?'VULNERABLE':'not in known affected range';}
 static function signatures($data,$extension){$hits=[]; $rules=['php_tag'=>'/<\?(?:php|=)/i','execution'=>'/\b(?:eval|assert|shell_exec|passthru|system|proc_open|popen)\s*\(/i','obfuscation'=>'/\b(?:base64_decode|gzinflate|gzuncompress|str_rot13)\s*\(/i','request_execution'=>'/(?:\$_(?:POST|GET|REQUEST|COOKIE)\s*\[.{0,100}\]).{0,200}(?:eval|system|shell_exec)|(?:eval|system|shell_exec)\s*\(.{0,150}\$_(?:POST|GET|REQUEST|COOKIE)/is','image_polyglot'=>'/<\?(?:php|=)/i'];foreach($rules as $id=>$re){if($id==='image_polyglot' && !in_array($extension,['png','jpg','jpeg','gif','webp','avif','bmp','ico'],true))continue;if($id==='php_tag' && !in_array($extension,['png','jpg','jpeg','gif','webp','avif','bmp','ico','svg','txt','dat'],true))continue;if(preg_match($re,$data))$hits[]=$id;}return $hits;}
 static function scan(){ $findings=[];$count=0;$limit=150000; $roots=self::roots();foreach($roots as $root){if(!is_dir($root))continue;$iter=new RecursiveIteratorIterator(new RecursiveDirectoryIterator($root,FilesystemIterator::SKIP_DOTS),RecursiveIteratorIterator::LEAVES_ONLY);foreach($iter as $file){if(++$count>$limit)break 2;if(!$file->isFile() || $file->isLink())continue;$path=$file->getPathname();$real=realpath($path);if(!$real || !self::within($real,$root))continue;$ext=strtolower(pathinfo($path,PATHINFO_EXTENSION));$executable=in_array($ext,['php','phtml','phar','php3','php4','php5','php7','php8','pht'],true);$size=$file->getSize();$data=$size<=2097152?@file_get_contents($path):@file_get_contents($path,false,null,0,131072);if($data===false)continue;$hits=self::signatures($data,$ext);if($executable)$hits[]='executable_in_writable_area';if($executable && preg_match('~^tmp_[0-9]+\.php$~i',basename($path)))$hits[]='observed_tmp_php_pattern';if(!$hits)continue;$severity=($executable || in_array('image_polyglot',$hits,true))?'high':(in_array('request_execution',$hits,true)?'high':'review');$id=hash('sha256',$real);$findings[$id]=['id'=>$id,'path'=>$real,'size'=>$size,'mtime'=>$file->getMTime(),'sha256'=>hash_file('sha256',$real),'signals'=>array_values(array_unique($hits)),'severity'=>$severity,'state'=>'active'];}}foreach((array)get_option(self::OPTION,[]) as $old_id=>$old){if(isset($old['state']) && $old['state']!=='active') $findings[$old_id]=$old;}update_option(self::OPTION,$findings,false);self::audit('scan',count($findings).' findings; '. $count.' files visited');return ['findings'=>$findings,'visited'=>$count,'truncated'=>$count>$limit];}
 static function within($path,$root){$base=realpath($root);return $base && strncmp($path,$base.DIRECTORY_SEPARATOR,strlen($base)+1)===0;}
 static function store(){ $dir=apply_filters('ayig_quarantine_path',dirname(ABSPATH).'/asenka-yootheme-image-guard-quarantine');if(strpos(wp_normalize_path(trailingslashit($dir)),wp_normalize_path(trailingslashit(ABSPATH)))===0)throw new RuntimeException('Quarantine location must be outside the WordPress installation. Set ayig_quarantine_path to a private directory.');if(!is_dir($dir))wp_mkdir_p($dir);if(!is_dir($dir) || !is_writable($dir))throw new RuntimeException('Private quarantine directory unavailable. Configure a writable location outside webroot.');return $dir;}
 static function audit($event,$message){$log=get_option(self::LOG,[]);$log[]= ['at'=>gmdate('c'),'user'=>get_current_user_id(),'event'=>$event,'detail'=>$message];update_option(self::LOG,array_slice($log,-300),false);}
 static function mutate($id,$operation){$items=get_option(self::OPTION,[]);if(!isset($items[$id]))throw new RuntimeException('Unknown finding');$f=&$items[$id];$dir=self::store();$manifest=$dir.'/'.$id.'.json';if($operation==='quarantine'){if($f['state']!=='active')throw new RuntimeException('Not active');$path=$f['path'];if(!is_file($path)||is_link($path)||!self::allowed($path)||!hash_equals($f['sha256'],hash_file('sha256',$path)))throw new RuntimeException('File changed or unsafe');$dest=$dir.'/'.$id.'.quarantine';if(file_exists($dest))throw new RuntimeException('Quarantine collision');if(!rename($path,$dest))throw new RuntimeException('Move failed');if(file_put_contents($manifest,wp_json_encode(['original'=>$path,'sha256'=>$f['sha256']]),LOCK_EX)===false){@rename($dest,$path);throw new RuntimeException('Could not write quarantine manifest');}@chmod($dest,0600);@chmod($manifest,0600);$f['state']='quarantined';}elseif($operation==='restore'){if($f['state']!=='quarantined')throw new RuntimeException('Not quarantined');$dest=$dir.'/'.$id.'.quarantine';if(!is_file($dest)||!hash_equals($f['sha256'],hash_file('sha256',$dest))||file_exists($f['path'])||!self::allowed($f['path']))throw new RuntimeException('Restore blocked');if(!rename($dest,$f['path']))throw new RuntimeException('Restore failed');$f['state']='active';@unlink($manifest);}elseif($operation==='delete'){if($f['state']!=='quarantined')throw new RuntimeException('Quarantine before permanent deletion');$dest=$dir.'/'.$id.'.quarantine';if(!is_file($dest)||!hash_equals($f['sha256'],hash_file('sha256',$dest)))throw new RuntimeException('Quarantined file changed');if(!unlink($dest))throw new RuntimeException('Delete failed');@unlink($manifest);$f['state']='deleted';}else throw new RuntimeException('Invalid operation');update_option(self::OPTION,$items,false);self::audit($operation,$f['path']);}
 static function allowed($path){foreach(self::roots() as $root)if(self::within($path,$root))return true;return false;}
 static function csv(){ $items=get_option(self::OPTION,[]);header('Content-Type: text/csv; charset=utf-8');header('Content-Disposition: attachment; filename="asenka-yootheme-image-guard-findings-'.gmdate('Ymd-His').'.csv"');header('X-Content-Type-Options: nosniff');$o=fopen('php://output','w');fputcsv($o,['Path','Severity','State','Signals','Size','Modified UTC','SHA256']);foreach($items as $f){$path=$f['path'];if(preg_match('/^[=+@\-\t\r]/',$path))$path="'".$path;fputcsv($o,[$path,$f['severity'],$f['state'],implode('|',$f['signals']),$f['size'],gmdate('c',$f['mtime']),$f['sha256']]);}fclose($o);exit;}
 static function action(){if(!current_user_can('manage_options'))wp_die('Forbidden',403);check_admin_referer('ayig');$op=sanitize_key($_POST['operation']??'');try{if($op==='scan')self::scan();elseif($op==='export')self::csv();else self::mutate(sanitize_text_field(wp_unslash($_POST['id']??'')),$op);$message='Action completed';}catch(Throwable $e){$message=$e->getMessage();}wp_safe_redirect(add_query_arg(['page'=>'asenka-yootheme-image-guard','notice'=>rawurlencode($message)],admin_url('tools.php')));exit;}
 static function form($operation,$id='',$label=''){echo '<form method="post" action="'.esc_url(admin_url('admin-post.php')).'" style="display:inline-block;margin-right:6px">';wp_nonce_field('ayig');echo '<input type="hidden" name="action" value="ayig"><input type="hidden" name="operation" value="'.esc_attr($operation).'"><input type="hidden" name="id" value="'.esc_attr($id).'"><button class="button" type="submit" '.($operation==='delete'?'onclick="return confirm(\'Permanently delete this quarantined file?\')"':'').'>'.esc_html($label?:ucfirst($operation)).'</button></form>';}
 static function page(){if(!current_user_can('manage_options'))return;echo '<div class="wrap"><h1>Asenka YOOtheme Image Guard v'.esc_html(self::VERSION).'</h1><p>Manual scanning only. Back up the site before modifying files. High severity is a review priority, not proof of malware.</p>';if(isset($_GET['notice']))echo '<div class="notice notice-info"><p>'.esc_html(sanitize_text_field(wp_unslash($_GET['notice']))).'</p></div>';self::form('scan','','Scan now');self::form('export','','Export CSV');echo '<p><a class="button" href="'.esc_url(admin_url('tools.php?page=ayig-updates')).'">GitHub updates &amp; release status</a></p>'; echo '<p><a class="button" href="'.esc_url(admin_url('tools.php?page=ayig-updates')).'">GitHub updates &amp; release status</a></p>'; echo '<h2>YOOtheme versions</h2><table class="widefat striped"><thead><tr><th>Type</th><th>Name</th><th>Version</th><th>Assessment</th></tr></thead><tbody>';foreach(self::versions() as $v)echo '<tr><td>'.esc_html($v['type']).'</td><td>'.esc_html($v['name']).'</td><td>'.esc_html($v['version']).'</td><td>'.esc_html($v['status']).'</td></tr>';echo '</tbody></table><h2>Findings</h2><table class="widefat striped"><thead><tr><th>File</th><th>Severity</th><th>Signals</th><th>Status</th><th>Actions</th></tr></thead><tbody>';foreach(get_option(self::OPTION,[]) as $f){echo '<tr><td><code>'.esc_html($f['path']).'</code></td><td>'.esc_html($f['severity']).'</td><td>'.esc_html(implode(', ',$f['signals'])).'</td><td>'.esc_html($f['state']).'</td><td>';if($f['state']==='active')self::form('quarantine',$f['id']);if($f['state']==='quarantined'){self::form('restore',$f['id']);self::form('delete',$f['id'],'Permanently delete');}echo '</td></tr>';}echo '</tbody></table><p>Scope: wp-content/uploads (including YOOtheme image cache). Theme PHP templates and plugin directories need separate review.</p></div>';}
 static function cli(){WP_CLI::add_command('ayig',new Asenka_YOOtheme_Image_Guard_CLI());}
}
if(defined('WP_CLI') && WP_CLI){class Asenka_YOOtheme_Image_Guard_CLI {function scan(){ $r=Asenka_YOOtheme_Image_Guard::scan();WP_CLI::success(count($r['findings']).' findings; '.$r['visited'].' files visited'.($r['truncated']?' (LIMIT REACHED)':''));}function versions(){WP_CLI\Utils\format_items('table',Asenka_YOOtheme_Image_Guard::versions(),['type','name','version','status']);}function findings($args,$assoc){$items=array_values(get_option(Asenka_YOOtheme_Image_Guard::OPTION,[]));foreach($items as &$f)$f['signals']=implode('|',$f['signals']);WP_CLI\Utils\format_items($assoc['format']??'table',$items,['id','path','severity','state','signals','sha256']);}function quarantine($args){Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','quarantine');WP_CLI::success('Quarantined');}function restore($args){Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','restore');WP_CLI::success('Restored');}function delete($args,$assoc){if(!isset($assoc['yes']))WP_CLI::error('Requires --yes');Asenka_YOOtheme_Image_Guard::mutate($args[0]??'','delete');WP_CLI::success('Deleted');}}}
